SELECT finalize(to_aggregate_state(
    (SELECT list(x ORDER BY y) EXPORT_STATE FROM (VALUES (10, 1), (30, 3), (20, 2)) t(x, y))::STRUCT(v0 INTEGER, v1 INTEGER)[],
    'list', ['INTEGER'], [NULL], [{'column': 1, 'order': 'ASC NULLS LAST'}]
));

WITH states AS (
    SELECT sum(v) EXPORT_STATE AS s FROM (VALUES (1), (2)) t(v)
)
SELECT finalize(combine_aggr(s, -1)) FROM states;

WITH d(i, v) AS (
	VALUES (1, 'nan'::DOUBLE), (2, 'nan'::DOUBLE), (3, 1.0), (4, 1.0), (5, 'nan'::DOUBLE)
)
SELECT i, mode(v) OVER (ORDER BY i ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)::VARCHAR
FROM d
ORDER BY i;

select k, v, mode(v) over (partition by k)
    from timestamps
    order by k, v;

SELECT count(DISTINCT s) FILTER (WHERE keep),
       string_agg(DISTINCT s, ',' ORDER BY s DESC) FILTER (WHERE keep)
FROM distinct_rewrite_order;

select
	count(distinct i) FILTER (WHERE i >= 20)
from tbl;

SELECT g, sum(CASE WHEN i%4=0 THEN 9000000000000000000::BIGINT END),
       sum(CASE WHEN i%4=1 THEN -9000000000000000000::BIGINT END)
FROM (SELECT i, (i//64)%2 AS g FROM range(8192) t(i)) t GROUP BY g ORDER BY g;

SELECT a as x FROM (VALUES (1),(2),(3)) t(a)
GROUP BY alias.x + 1
ORDER BY alias.x;

with stage as (
      select
          [1,2,3] as c1,
          [4,5,6] as c2
)
select
     list_transform(
       c1,
       lambda x: list_bool_or(
          list_transform(
            c2,
            lambda y: y == x
          )
       )
     ) as c3
from stage;

SELECT (WITH keys AS (SELECT unnest(json_keys(example)) AS k), nonNull AS (
    		SELECT keys.k, example->keys.k AS v
    		FROM keys WHERE nullif(v, 'null') IS NOT NULL
    	)
    	SELECT json_group_object(nonNull.k, nonNull.v)
    	FROM nonNull
)
FROM testjson;

select upper(col1)
from (
	select *
	from t1
	union
	select *
	from t2
) d;

SELECT TRY_CAST(col AS MAP(VARCHAR, integer))
FROM (
    SELECT CASE WHEN (i % 5 == 0) THEN NULL else {'a': i::varchar} END as col
    FROM range(1, 1001) t(i)
)
LIMIT 5;

SELECT p.oid = c.parent_schema_oid
FROM duckdb_schemas() c, duckdb_schemas() p
WHERE c.schema_name = 'child' AND p.schema_name = 's1' AND p.database_name = 'memory';

SELECT list(DISTINCT s COLLATE de ORDER BY s COLLATE de),
       string_agg(DISTINCT s COLLATE de, ',' ORDER BY s COLLATE de)
FROM (VALUES ('GÖTHE'), ('Z'), ('GÖTHE')) t(s);

SELECT typeof(a), typeof(b), typeof(c)
FROM  read_csv_auto('{TEST_DIR}/ubn*.csv', UNION_BY_NAME=TRUE, dtypes={'xxx': TINYINT})
LIMIT 1;

SELECT typeof(first(column0)), typeof(first(column1)), COUNT(*), SUM(column0), MAX(len(column1)) FROM read_csv_auto(
    '{DATA_DIR}/csv/error/mismatch/big_bad*.csv',
