    columns = {'name': 'VARCHAR', 'age': 'INTEGER', 'current_day': 'DATE', 'barks': 'INTEGER'},
    store_rejects = true, auto_detect=false, header = 1, max_line_size=40);

FROM read_csv(
    '{DATA_DIR}/csv/mixed_double.csv',
    auto_detect = false,
    header = true,
     columns = {
      'A': 'INTEGER',
      'B': 'DOUBLE',
    },
    ignore_errors = true
);

SELECT count(*)
FROM read_parquet('{TEST_DIR}/bloom_in.parquet')
WHERE r IN (NULL);

SELECT bool_and(bloom_filter_excludes)
FROM parquet_bloom_probe('{TEST_DIR}/bloom_temporal.parquet', 'ts',
                         TIMESTAMP '2000-01-01' + INTERVAL 1001 SECOND);

SELECT count(*)
FROM '{TEST_DIR}/bloom_blob.parquet' lhs
JOIN '{TEST_DIR}/bloom_blob.parquet' rhs ON lhs.b = rhs.b;

SELECT count(*)
FROM read_parquet('{TEST_DIR}/bloom_ndf_signed_zero.parquet')
WHERE x IS NOT DISTINCT FROM 0.0;

SELECT count(*)
FROM (
	SELECT i, row_number() OVER () - 1 AS expected
	FROM read_parquet('{TEST_DIR}/cte_nested_batch_exchange.parquet')
)
WHERE i != expected;

SELECT count(*), min(id), max(id) FROM read_parquet(['{TEST_DIR}/column_stats_1.parquet', '{TEST_DIR}/column_stats_2.parquet'],
    column_statistics := MAP {'id': MAP {'min': '0', 'max': '199999', 'count': '200000', 'null_count': '0', 'distinct_count': '200000'}})
WHERE id >= 150000;

SELECT a 
FROM parquet_scan(['{TEST_DIR}/ubn2.parquet', '{TEST_DIR}/ubn1.parquet', '{TEST_DIR}/ubn3.parquet'])
ORDER BY a;

SELECT regexp_extract(replace(filename, '\', '/'), 'partition_path_csv/(.*)/[^/]*$', 1) AS dir, count(*)
FROM read_csv('{TEST_DIR}/partition_path_csv/*/*.csv', hive_partitioning = false, filename = true)
GROUP BY dir ORDER BY dir;

SELECT regexp_extract(replace(filename, '\', '/'), 'partition_path_json_columns/(.*)/[^/]*$', 1) AS dir, count(*), count(region)
FROM read_json('{TEST_DIR}/partition_path_json_columns/*/*.json', hive_partitioning = false, filename = true)
GROUP BY dir ORDER BY dir;

WITH ins AS (
    INSERT INTO t VALUES (42, 42) RETURNING i
)
SELECT * FROM ins;

WITH ins AS (INSERT INTO t_aux VALUES (99, 99) RETURNING i),
     del AS (DELETE FROM t1 WHERE i <= 2 RETURNING i)
SELECT * FROM del;

WITH t(i) AS MATERIALIZED (
	SELECT i FROM range(1000000) tbl(i)
)
SELECT (SELECT i FROM t LIMIT 1 OFFSET 100000), (SELECT i FROM t LIMIT 1 OFFSET 900000);

WITH c(i) AS MATERIALIZED (VALUES (1), (2), (NULL))
SELECT sum((SELECT i FROM c WHERE c.i=o.i))
FROM (VALUES (1), (3)) o(i);

WITH t(x) AS MATERIALIZED (
  WITH u(x) AS MATERIALIZED (
    SELECT 42
  ) SELECT * FROM u
) SELECT * FROM t;

WITH RECURSIVE t(i, identity_payload) AS (
	SELECT 1, 0
	UNION
	SELECT i, identity_payload + 1 FROM t WHERE identity_payload < 3
)
SELECT count(i) FROM t;

WITH RECURSIVE t(k, v) USING KEY (k) AS (
	SELECT i, 0 FROM range(0) r(i)
	UNION ALL
	SELECT k, v + 1 FROM t WHERE v < 0
)
SELECT count(*) FROM t;

WITH RECURSIVE t(k, total) USING KEY (k, sum(total)) AS (
	VALUES (1, 1), (1, 2)
	UNION
	SELECT k, 0 FROM t WHERE false
)
TABLE t;

WITH RECURSIVE t(k, v) USING KEY (k) AS (
	SELECT 1, ['a' COLLATE nocase]
	UNION
	SELECT CASE ascii(v[1]) WHEN 97 THEN 1 ELSE 2 END, ['A' COLLATE nocase] FROM t
)
TABLE t;

WITH RECURSIVE t(k, v) USING KEY (k, min(v)) AS (
	SELECT array_value('a' COLLATE nocase), 2
	UNION
	SELECT array_value('A' COLLATE nocase), v - 1 FROM t WHERE v > 0
)
SELECT count(*), min(v), min(k[1]) FROM t;

SELECT count(*) FROM (
	WITH RECURSIVE t(i) AS (
		SELECT 0
		UNION ALL
		SELECT i + 1 FROM t
	)
	SELECT i FROM t LIMIT 2048
);

WITH candidates AS MATERIALIZED (
	SELECT i FROM range(8192) r(i)
)
SELECT count(*), sum(i)
FROM candidates c
WHERE EXISTS (
	WITH RECURSIVE t(v) AS (
		VALUES (0)
		UNION ALL
		SELECT v + 1 FROM t WHERE v < c.i % 4
	)
	SELECT 1 FROM t WHERE v = c.i % 4
);

WITH RECURSIVE t(i) AS (
	SELECT 1
	UNION
	SELECT i + 1 FROM t WHERE i < 1000
)
SELECT sum(i) FROM t;

WITH RECURSIVE
  t(b) AS MATERIALIZED (
    (WITH helper(c) AS (
      SELECT 5
    )
    SELECT * FROM helper h
    UNION
    SELECT 7
    )
  )
SELECT * FROM t ORDER BY b;

