SELECT d, DATE_PART(['year', 'month', 'day', 'epoch'], d) AS parts
FROM dates
ORDER BY 1;

SELECT i, DATE_PART(['hour', 'minute', 'second', 'epoch'], i) AS parts
FROM intervals
ORDER BY 1;

SELECT generate_series(start, stop, step) FROM (VALUES
	(timestamptz '2020-01-01', timestamptz '2020-07-01', interval '3' month),
	(timestamptz '2020-12-04', timestamptz '2020-09-01', interval '-1 month -1 day'),
	(timestamptz '2020-03-08', timestamptz '2020-03-09', interval '6' hour),
	(timestamptz '2020-11-02', timestamptz '2020-11-01', interval '-43200' second),
) AS _(start, stop, step);

with base as (
	select [4,5,6] as l
)
select [x for x,i in l if i != 2] as filtered from base;

SELECT list_reduce(l, lambda acc, x: acc + x + v + initial, 0),
       list_reduce(l, lambda acc, x, i: acc + x + v + i, 0)
FROM t;

SELECT COUNT(*) FROM read_parquet('{TEST_DIR}/my_file_' ||
list_aggr(list_transform(list_filter(['s', 'c', 'b', NULL, 'a'], lambda x: x IS NOT NULL AND x != 's'),
lambda s: lower(s)), 'string_agg', '') || '.parquet');

SELECT d, DATE_PART('{partcode}', d) AS p, DATE_PART(['{partcode}'], d) AS st
FROM times
WHERE p <> st['{partcode}'];

SELECT iv, ts + iv FROM limits, intervals
WHERE label = 'tsmax'
  AND iv < (INTERVAL (-1) millisecond);

SELECT count(*), bool_and(
    v[1]::VARCHAR IS NOT DISTINCT FROM a AND
    v[2]::VARCHAR IS NOT DISTINCT FROM b AND
    v[3]::VARCHAR IS NOT DISTINCT FROM c
) FROM encoded;

SELECT variant_extract_string({'geometry': geometry}::VARIANT, '')
FROM test_all_types()
WHERE bool = false;

SELECT [*COLUMNS(*)] FROM (
	SELECT variant_type(
		COLUMNS(lambda c: NOT regexp_matches(c, 'array|struct|map|union|tuple'))::VARIANT
	)
	FROM test_all_types()
	-- strip NULLs from output
	WHERE bool IS NOT NULL
);

SELECT payload
FROM db.t
WHERE k = repeat('a', 80) || 'gath' || repeat('b', 80) || 'tail';

SELECT * FROM left_table l
ASOF LEFT JOIN right_table r
ON l.symbol = r.symbol AND l.ts >= r.ts AND l.price + r.bid > 300;

SELECT * FROM r t1
ASOF LEFT JOIN (SELECT * FROM a EXCEPT ALL SELECT * FROM b) t0 ON t1.d >= t0.d
ORDER BY ALL;

SELECT in_dim, count(*) FROM (
    SELECT f.id, f.k IN (SELECT k FROM dim WHERE name IN ('Alpha','Beta')) AS in_dim FROM fact f
) GROUP BY in_dim ORDER BY in_dim NULLS FIRST

SELECT x.col1, y.col1 FROM tbl_null x JOIN tbl_null y
ON x.col0 = y.col0 AND (x.col1 IS DISTINCT FROM y.col1)
ORDER BY x.col1, y.col1;

SELECT x.col1, y.col1 FROM tbl_l_null x JOIN tbl_l_null y
ON x.col0 = y.col0 AND x.col1 = y.col1
ORDER BY x.col1;

SELECT x.col1, y.col1 FROM tbl_s_null x JOIN tbl_s_null y
ON x.col0 = y.col0 AND x.col1 = y.col1
ORDER BY x.col1.x, y.col1.x NULLS LAST;

SELECT t.product_id FROM (SELECT [1.0,0.0,0.0]::FLOAT[3] AS embedding) q
  INNER JOIN products t EXACT NEAREST 3 BY DISTANCE array_distance(q.embedding, t.embedding)
  ORDER BY t.product_id;

SELECT q.id, t.y FROM lnums q
  INNER JOIN all_null t NEAREST 2 BY DISTANCE abs(q.x - t.y)
  ORDER BY q.id;

SELECT *
FROM LATERAL (SELECT r.b) l(a)
RIGHT JOIN (VALUES (1)) r(b) ON EXISTS (
	SELECT 1 WHERE l.a = r.b
);

SELECT l.a, r.b
FROM pair_l l
FULL OUTER JOIN pair_r r ON r.b IN (
	SELECT s.b FROM pair_s s WHERE s.a = l.a
)
ORDER BY l.a NULLS LAST, r.b NULLS LAST;

SELECT l.rowid, l.a, r.rowid, r.b
FROM pair_rowid_l l
FULL OUTER JOIN pair_rowid_r r ON EXISTS (
	SELECT 1 FROM pair_rowid_s s WHERE s.a = l.a AND s.b = r.b
)
ORDER BY ALL;

SELECT l.a, l.x, r.b
FROM pair_l l
LEFT JOIN pair_r r ON l.a IN (
	SELECT s.a FROM pair_s s WHERE s.b = r.b
)
ORDER BY l.x, r.b NULLS LAST;

WITH q AS (
	SELECT count(*)::INTEGER AS count_value
	FROM pair_left_effect_l l
	SEMI JOIN (SELECT b, nextval('pair_exists_right_effect_seq') AS v FROM pair_left_effect_r) r ON EXISTS (
		SELECT 1 WHERE l.a = r.v
	)
)
SELECT count_value, currval('pair_exists_right_effect_seq') FROM q;

SELECT id, parse_filename(filename) FROM read_csv('{TEMP_DIR}/schema_*.csv', schema=map {
	'a': {name: 'id', type: 'BIGINT', default_value: NULL}
}, filename=true) ORDER BY id

SELECT list_transform(
	list_filter(list_transform(l, lambda x: struct_pack(filter := x, result := x)),
	            lambda s: s.filter::DECIMAL(1,0)::BOOLEAN),
	lambda s: s.result
) FROM (VALUES ([0.1,0.9])) t(l);

SELECT i::DOUBLE = 1, i::DOUBLE < 1.5, i::DOUBLE IS DISTINCT FROM NULL, i::DOUBLE IS NOT DISTINCT FROM 1
FROM integers
ORDER BY i NULLS FIRST;

select timestamp_str, cast(timestamp_str as timestamp)
from table1
where cast(timestamp_str as timestamp) > cast('2024-05-03T01:00:00+00:00' as timestamp);

from (
