    SELECT i FROM test_table
)
SELECT COUNT(*) FROM base USING SAMPLE 37 ROWS (system);

SELECT count(*) FROM export_dates WHERE
date_part('year',ts) IS DISTINCT FROM year(ts)
OR date_part('epoch',ts) IS DISTINCT FROM epoch(ts);

SELECT row(map([1, 2], [1, NULL::INT]), 0) IN (
	SELECT * FROM (VALUES (map([1, 2], [1, 2]), 0)) rhs(a, b)
)

SELECT table_schema, table_name, SUBSTR (view_definition, 1, 32) AS view_definition_substr, check_option, is_updatable, is_insertable_into, is_trigger_updatable, is_trigger_deletable, is_trigger_insertable_into
FROM information_schema.views
WHERE table_schema = 'scheme' AND table_name = 'emp_dept_view';

SELECT remap_struct(
	[ {'first_name': 'Alice', 'age': 43} ],
	NULL::STRUCT(age INTEGER, given_name VARCHAR)[],
	{ 'list': ROW('bag', { 'age': 'age', 'given_name': 'first_name' }) },
	NULL
);

SELECT id, nested.inner_struct.tag, nested.inner_struct.payload.obj.a::INTEGER,
       nested.inner_struct.payload.obj.b::VARCHAR
FROM (SELECT * FROM nested_variant) ORDER BY id;

SELECT COUNT(*) OVER (
  ORDER BY id ROWS BETWEEN CURRENT ROW AND off FOLLOWING
)
FROM (VALUES (1, -1)) AS src(id, off);

SELECT id, string_agg(id, ' ') OVER (PARTITION BY ch ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) 
FROM t1
ORDER BY 1;

select i, nth_value(i, 2049) over(ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) n
from range(2049) tbl(i)
QUALIFY n IS NOT NULL;

WITH w AS (
	SELECT i, FIRST_VALUE(CASE WHEN i = 2048 THEN i END IGNORE NULLS) OVER (
		ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x
	FROM range(6144) AS r(i)
)
SELECT COUNT(*), COUNT(*) FILTER (WHERE x IS DISTINCT FROM CASE WHEN i >= 2048 THEN 2048 END) FROM w;

SELECT count(x) FROM (
    SELECT histogram(i) OVER (ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING EXCLUDE CURRENT ROW) x
    FROM range(3) t(i)
);

SELECT sum(b) OVER (
    ORDER BY a NULLS LAST ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING
  ) FROM t1 ORDER BY 1 NULLS LAST;

SELECT nth_value(peer, 5) OVER (
           ORDER BY peer ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE TIES
       ), peer
FROM value_edges ORDER BY peer, i;

SELECT count(x) FROM (
    SELECT last_value(v ORDER BY i) OVER (
        ORDER BY peer ROWS BETWEEN CURRENT ROW AND CURRENT ROW EXCLUDE GROUP
    ) AS x
    FROM value_edges
);
